package com.fream.back.domain.shipment.service.query;

import com.fream.back.domain.shipment.dto.ShipmentResponseDto;
import com.fream.back.domain.shipment.entity.Shipment;
import com.fream.back.domain.shipment.exception.ShipmentErrorCode;
import com.fream.back.domain.shipment.exception.ShipmentException;
import com.fream.back.domain.shipment.exception.ShipmentNotFoundException;
import com.fream.back.domain.shipment.exception.ShipmentProductNotFoundException;
import com.fream.back.domain.shipment.repository.ShipmentRepository;
import com.fream.back.domain.product.entity.Product;
import com.fream.back.domain.product.repository.ProductRepository;
import com.fream.back.global.utils.PersonalDataEncryptionUtil;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
@Slf4j
public class ShipmentQueryService {

    private final ProductRepository userRepository;
    private final ShipmentRepository addressRepository;
    private final PersonalDataEncryptionUtil encryptionUtil;


    @Transactional(readOnly = true)
    public List<ShipmentResponseDto> getAddresses(String email) {
        try {
            log.info("주소 목록 조회 시작: 사용자={}", email);


            String encryptedEmail = encryptionUtil.deterministicEncrypt(email);
            Product user = userRepository.findByEmail(encryptedEmail)
                    .orElseThrow(() -> new ShipmentProductNotFoundException(
                            "이메일 '" + email + "'에 해당하는 사용자를 찾을 수 없습니다."
                    ));

            List<ShipmentResponseDto> addresses = user.getAddresses().stream()
                    .map(address -> new ShipmentResponseDto(
                            address.getId(),

                            encryptionUtil.deterministicDecrypt(address.getRecipientName()),
                            encryptionUtil.deterministicDecrypt(address.getPhoneNumber()),
                            encryptionUtil.deterministicDecrypt(address.getZipCode()),
                            encryptionUtil.deterministicDecrypt(address.getAddress()),

                            address.getDetailedAddress() != null ?
                                    encryptionUtil.decrypt(address.getDetailedAddress()) : null,
                            address.isDefault()))
                    .collect(Collectors.toList());

            log.info("주소 목록 조회 완료: 사용자={}, 조회된 주소 수={}", email, addresses.size());
            return addresses;
        } catch (ShipmentException e) {
            throw e;
        } catch (Exception e) {
            log.error("주소 목록 조회 중 오류 발생: 사용자={}, 오류={}", email, e.getMessage(), e);
            throw new ShipmentException(ShipmentErrorCode.ADDRESS_QUERY_ERROR, e);
        }
    }


    @Transactional(readOnly = true)
    public ShipmentResponseDto getAddress(String email, Long addressId) {
        try {
            log.info("단일 주소 조회 시작: 사용자={}, 주소ID={}", email, addressId);


            String encryptedEmail = encryptionUtil.deterministicEncrypt(email);
            Product user = userRepository.findByEmail(encryptedEmail)
                    .orElseThrow(() -> new ShipmentProductNotFoundException(
                            "이메일 '" + email + "'에 해당하는 사용자를 찾을 수 없습니다."
                    ));

            Shipment address = addressRepository.findByIdAndUser(addressId, user)
                    .orElseThrow(() -> new ShipmentNotFoundException(
                            "주소 ID '" + addressId + "'에 해당하는 주소를 찾을 수 없습니다."
                    ));


            ShipmentResponseDto responseDto = new ShipmentResponseDto(
                    address.getId(),

                    encryptionUtil.deterministicDecrypt(address.getRecipientName()),
                    encryptionUtil.deterministicDecrypt(address.getPhoneNumber()),
                    encryptionUtil.deterministicDecrypt(address.getZipCode()),
                    encryptionUtil.deterministicDecrypt(address.getAddress()),

                    address.getDetailedAddress() != null ?
                            encryptionUtil.decrypt(address.getDetailedAddress()) : null,
                    address.isDefault()
            );

            log.info("단일 주소 조회 완료: 사용자={}, 주소ID={}", email, addressId);
            return responseDto;
        } catch (ShipmentException e) {
            throw e;
        } catch (Exception e) {
            log.error("단일 주소 조회 중 오류 발생: 사용자={}, 주소ID={}, 오류={}",
                    email, addressId, e.getMessage(), e);
            throw new ShipmentException(ShipmentErrorCode.ADDRESS_QUERY_ERROR, e);
        }
    }




    @Transactional(readOnly = true)
    public List<ShipmentResponseDto> searchAddressesByRecipientName(String email, String recipientName) {
        try {
            log.info("이름으로 주소 검색 시작: 사용자={}, 검색어={}", email, recipientName);


            String encryptedEmail = encryptionUtil.deterministicEncrypt(email);
            Product user = userRepository.findByEmail(encryptedEmail)
                    .orElseThrow(() -> new ShipmentProductNotFoundException(
                            "이메일 '" + email + "'에 해당하는 사용자를 찾을 수 없습니다."
                    ));


            String encryptedSearchTerm = encryptionUtil.encryptForSearch(recipientName);


            List<Shipment> foundAddresses = addressRepository.findByUserAndRecipientName(user, encryptedSearchTerm);

            List<ShipmentResponseDto> addresses = foundAddresses.stream()
                    .map(address -> new ShipmentResponseDto(
                            address.getId(),
                            encryptionUtil.deterministicDecrypt(address.getRecipientName()),
                            encryptionUtil.deterministicDecrypt(address.getPhoneNumber()),
                            encryptionUtil.deterministicDecrypt(address.getZipCode()),
                            encryptionUtil.deterministicDecrypt(address.getAddress()),
                            address.getDetailedAddress() != null ?
                                    encryptionUtil.decrypt(address.getDetailedAddress()) : null,
                            address.isDefault()))
                    .collect(Collectors.toList());

            log.info("이름으로 주소 검색 완료: 사용자={}, 검색어={}, 결과 수={}",
                    email, recipientName, addresses.size());
            return addresses;
        } catch (ShipmentException e) {
            throw e;
        } catch (Exception e) {
            log.error("이름으로 주소 검색 중 오류 발생: 사용자={}, 검색어={}, 오류={}",
                    email, recipientName, e.getMessage(), e);
            throw new ShipmentException(ShipmentErrorCode.ADDRESS_QUERY_ERROR, e);
        }
    }




    @Transactional(readOnly = true)
    public List<ShipmentResponseDto> searchAddressesByPhoneNumber(String email, String phoneNumber) {
        try {
            log.info("전화번호로 주소 검색 시작: 사용자={}, 검색어={}", email, phoneNumber);


            String encryptedEmail = encryptionUtil.deterministicEncrypt(email);
            Product user = userRepository.findByEmail(encryptedEmail)
                    .orElseThrow(() -> new ShipmentProductNotFoundException(
                            "이메일 '" + email + "'에 해당하는 사용자를 찾을 수 없습니다."
                    ));


            String encryptedSearchTerm = encryptionUtil.encryptForSearch(phoneNumber);


            List<Shipment> foundAddresses = addressRepository.findByUserAndPhoneNumber(user, encryptedSearchTerm);

            List<ShipmentResponseDto> addresses = foundAddresses.stream()
                    .map(address -> new ShipmentResponseDto(
                            address.getId(),
                            encryptionUtil.deterministicDecrypt(address.getRecipientName()),
                            encryptionUtil.deterministicDecrypt(address.getPhoneNumber()),
                            encryptionUtil.deterministicDecrypt(address.getZipCode()),
                            encryptionUtil.deterministicDecrypt(address.getAddress()),
                            address.getDetailedAddress() != null ?
                                    encryptionUtil.decrypt(address.getDetailedAddress()) : null,
                            address.isDefault()))
                    .collect(Collectors.toList());

            log.info("전화번호로 주소 검색 완료: 사용자={}, 검색어={}, 결과 수={}",
                    email, phoneNumber, addresses.size());
            return addresses;
        } catch (ShipmentException e) {
            throw e;
        } catch (Exception e) {
            log.error("전화번호로 주소 검색 중 오류 발생: 사용자={}, 검색어={}, 오류={}",
                    email, phoneNumber, e.getMessage(), e);
            throw new ShipmentException(ShipmentErrorCode.ADDRESS_QUERY_ERROR, e);
        }
    }
